import{_ as o,o as t,c as a,a2 as i}from"./chunks/framework.BN2sqjC1.js";const h=JSON.parse('{"title":"ADR-0022 — Resilienza: fault injection, chaos su Helm, backup/PITR (M7-WP2b)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0022-resilience-details.md","filePath":"adr/0022-resilience-details.md"}'),r={name:"adr/0022-resilience-details.md"};function c(n,e,d,s,l,u){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-0022-—-resilienza-fault-injection-chaos-su-helm-backup-pitr-m7-wp2b" tabindex="-1">ADR-0022 — Resilienza: fault injection, chaos su Helm, backup/PITR (M7-WP2b) <a class="header-anchor" href="#adr-0022-—-resilienza-fault-injection-chaos-su-helm-backup-pitr-m7-wp2b" aria-label="Permalink to &quot;ADR-0022 — Resilienza: fault injection, chaos su Helm, backup/PITR (M7-WP2b)&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata</td></tr><tr><td><strong>Recepito in</strong></td><td><code>Specifications.md</code> v1.4 (2026-11-02): §1.6, §3.1, §3.4.2, §3.4.4, Appendice A (Appendice C.4)</td></tr><tr><td><strong>Data</strong></td><td>2026-10-27</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>Appendice A (Disponibilità, Affidabilità dati); §3.4.4 (pull/cursor); D-02, D-03</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>no</td></tr></tbody></table><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>Appendice A richiede RPO ≤ 5 min, scritture client atomiche, nessuna perdita silenziosa e cloud 99,9 % (&quot;SLO + chaos test&quot;, &quot;test di fault injection&quot;). Ogni scenario sotto asserisce che il guasto sia stato davvero iniettato prima di valutare l&#39;esito.</p><h2 id="garanzie-verificate" tabindex="-1">Garanzie verificate <a class="header-anchor" href="#garanzie-verificate" aria-label="Permalink to &quot;Garanzie verificate&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scenario</th><th>Iniezione</th><th>Esito</th></tr></thead><tbody><tr><td>Kill del cloud a metà <code>commit</code> (40 op)</td><td>SIGKILL del processo reale mentre una op è bloccata in PG (trigger <code>pg_sleep</code>); <code>pg_terminate_backend</code>; abort del client</td><td>Nessuna revisione/file/contatore parziale; retry con gli stessi <code>op_id</code> → 40 accettate, <code>seq</code> contigui, secondo retry identico, nessun duplicato</td></tr><tr><td>Upload blob / tus interrotto</td><td>Proxy TCP che taglia la connessione dopo N byte</td><td>Nulla pubblicato; HEAD riporta l&#39;ultimo offset completo; ripresa e digest verificato; chunk corrotto → 400 e sessione scartata</td></tr><tr><td><code>WriteAtomic</code></td><td>Processo figlio con <code>os.Exit</code> dopo tmp-write, fsync, prima del rename, dopo il rename (crea e sovrascrive)</td><td>Il target è sempre il vecchio o il nuovo contenuto, mai parziale</td></tr><tr><td>Pull con rete persa</td><td>Transport che taglia <code>changes</code> alla 2ª pagina o tronca un download (con errore e in silenzio)</td><td>Cursore = fine dell&#39;ultima pagina applicata (o invariato), nessun file a metà, converge senza conflitti; il digest intercetta il troncamento silenzioso</td></tr><tr><td>Restart di PostgreSQL ×3</td><td><code>docker stop/start</code> sotto il cloud in esecuzione</td><td><code>/readyz</code> 503 con check <code>database</code>, <code>/healthz</code> resta 200, richieste → 500 problem+json con <code>code</code> (mai 401), pronto di nuovo in ~0,3 s, zero richieste fallite dopo la readiness, goroutine e connessioni stabili</td></tr><tr><td>SIGTERM</td><td>Commit in volo + SIGTERM</td><td><code>/readyz</code> 503 subito, servizio attivo durante il drain, la richiesta in volo termina 200, il processo esce da solo</td></tr></tbody></table><h2 id="bug-trovati-e-corretti" tabindex="-1">Bug trovati e corretti <a class="header-anchor" href="#bug-trovati-e-corretti" aria-label="Permalink to &quot;Bug trovati e corretti&quot;">​</a></h2><ol><li><strong>Shutdown senza drain</strong>: la readiness non cambiava prima dello stop e le connessioni SSE bloccavano <code>Shutdown</code> fino al timeout. Ora <code>httpserver.Serve</code>: readiness → 503, drain <code>SHUTDOWN_DRAIN</code> (default 5 s), chiusura degli stream, poi <code>Shutdown</code>. Misura su k3d con 3 repliche: rolling restart con drain 0 s = 9 timeout su 130 richieste (93,1 %), con 5 s = 0 falliti.</li><li><strong>File di staging mai esclusi</strong>: <code>.memobrain-tmp-*</code> non era in <code>pathrules.IsExcluded</code>, quindi un crash durante <code>WriteAtomic</code> lasciava un file che <code>Walk</code> (sync, indicizzatore) vedeva e sincronizzava. Ora escluso; <code>FS.CleanStaleTemp</code> lo rimuove (&gt; 1 min) al primo sync dell&#39;engine.</li><li><strong><code>changes</code> con cursore oltre <code>last_seq</code></strong> rispondeva una pagina vuota: dopo un PITR il client avrebbe saltato in silenzio i nuovi commit che riusano quei <code>seq</code>. Ora 410 <code>CURSOR_EXPIRED</code> (il client fa bootstrap; i file persi dal server vanno nel <code>.trash/</code> locale, non cancellati).</li><li><code>authtest.New</code> aveva una data race (letta da un processo esterno prima dell&#39;assegnazione di <code>Server</code>).</li></ol><h2 id="chaos-sul-chart-helm-k3d-memobrain-chaos-3-repliche-api-sonda-10-hz-get-me-autenticato-con-token-keycloak-reale-finestra-170-s" tabindex="-1">Chaos sul chart Helm (k3d <code>memobrain-chaos-*</code>, 3 repliche API, sonda 10 Hz <code>GET /me</code> autenticato con token Keycloak reale, finestra ~170 s) <a class="header-anchor" href="#chaos-sul-chart-helm-k3d-memobrain-chaos-3-repliche-api-sonda-10-hz-get-me-autenticato-con-token-keycloak-reale-finestra-170-s" aria-label="Permalink to &quot;Chaos sul chart Helm (k3d `memobrain-chaos-*`, 3 repliche API, sonda 10 Hz `GET /me` autenticato con token Keycloak reale, finestra ~170 s)&quot;">​</a></h2><p>Kill SIGKILL ×3, delete graceful ×2, rolling restart, crash di PostgreSQL (SIGKILL al checkpointer): <strong><code>/me</code> 100 % (0/1562) escludendo il crash di PG; 99,885 % complessivo</strong> (2 × 500 in ~0,2 s di crash recovery). Senza drain (0 s): 99,36 % escludendo PG. Il 99,9 % è dunque raggiunto <em>in finestra</em> con ≥ 2 repliche e drain; su 1500 campioni la risoluzione è 0,07 %: <strong>non dimostra 99,9 % mensile</strong>.</p><p><strong>Lacune del chart</strong> (da M7-WP3, non toccato): nessun PodDisruptionBudget; nessun anti-affinity/topologySpread; <code>SHUTDOWN_DRAIN</code> non impostato né <code>terminationGracePeriodSeconds</code> esplicito (deve essere &gt; drain + <code>SHUTDOWN_TIMEOUT</code>); readiness con <code>periodSeconds 10</code>, <code>timeout 1s</code>; strategia di default 25 %/25 % (meglio <code>maxUnavailable: 0</code>); <code>values-k3d</code> usa 1 replica (downtime a ogni rollout); PostgreSQL singolo pod (ogni suo guasto è downtime: serve HA o servizio gestito). Gli errori in outage sono 500 <code>INTERNAL</code>, non 503 con <code>Retry-After</code>: un codice <code>UNAVAILABLE</code> richiede modifica di OpenAPI (non fatta). Il desktop tratta i 5xx come errore, non come offline.</p><h2 id="backup-pitr" tabindex="-1">Backup/PITR <a class="header-anchor" href="#backup-pitr" aria-label="Permalink to &quot;Backup/PITR&quot;">​</a></h2><p><code>docs/runbook/backup-restore.md</code> provato da <code>scripts/chaos/restore-drill.sh</code> (container usa e getta): WAL archiving + <code>pg_basebackup</code>, distruzione del DB, <strong>PITR a T eseguito</strong> (a+b presenti, c assente), changelog <code>1..N</code> contiguo, blob scaricati con digest, coerenza DB↔bucket, oggetto cancellato/sovrascritto riparato dalle versioni, dump logico ripristinato; RTO del drill 33 s (dataset minuscolo). <strong>RustFS supporta versioning e lifecycle</strong>.</p><h2 id="limiti" tabindex="-1">Limiti <a class="header-anchor" href="#limiti" aria-label="Permalink to &quot;Limiti&quot;">​</a></h2><p>Nessun test di Keycloak, di PG HA né di GC dei blob tra T e restore; WAL su volume locale; RTO reale da misurare con dati veri.</p>',15)])])}const m=o(r,[["render",c]]);export{h as __pageData,m as default};
